lessons.viewSource:
view diagram "03 / Logical relational schema" {
    data: [@c.tables, @c.domains];
    format: @fmt.shared.technical;
    style: @fmt.shared.classic;
    layout: @fmt.shared.row;
    select: [@c.tables.line, @c.tables.orders, @c.tables.customer];
    publication { width: 1580px; height: 440px; }
    legend { keys: { "tables.r_line_order": 1, "tables.r_order_customer": 2 }; }
}

view diagram "04 / SQL object dependencies" {
    data: [@s.model, @c.tables, @c.domains];
    format: @fmt.shared.technical;
    style: @fmt.shared.classic;
    layout: @fmt.shared.row;
    select: [@s.model.routine, @s.model.view, @c.tables.orders];
    publication { width: 1580px; height: 440px; }
    legend { keys: { "model.r_routine_view": 1, "model.r_view_orders": 2 }; }
}

view diagram "05 / Nested document structure" {
    data: [@d.model];
    format: @fmt.shared.technical;
    style: @fmt.shared.classic;
    layout: @fmt.shared.row;
    select: [@d.model.profiles, @d.model.contacts, @d.model.contact];
    publication { width: 1580px; height: 440px; }
    legend { keys: { "model.r_a": 1, "model.r_b": 2 }; }
}

view diagram "06 / Property-graph schema" {
    data: [@g.model];
    format: @fmt.shared.technical;
    style: @fmt.shared.neo;
    layout: @fmt.shared.row;
    select: [@g.model.customer, @g.model.purchased, @g.model.product];
    publication { width: 1580px; height: 440px; }
    legend { keys: { "model.r_source": 1, "model.r_target": 2 }; }
}

view diagram "07 / Key-value design" {
    data: [@k.kv];
    format: @fmt.shared.technical;
    style: @fmt.shared.classic;
    layout: @fmt.shared.row;
    select: [@k.kv.key, @k.kv.sessions, @k.kv.value];
    publication { width: 1580px; height: 440px; }
    legend { keys: { "kv.r_a": 1, "kv.r_b": 2 }; }
}

view wide_column "07b / Wide-column access pattern" {
    data: [@k.wide]; format: @fmt.shared.technical;
    select: [@k.wide.query, @k.wide.readings, @k.wide.key];
    legend { keys: { "wide.r_a": 1, "wide.r_b": 2 }; }
}

view diagram "08 / Domain discovery and binding" {
    data: [@c.tables, @d.model, @c.domains];
    format: @fmt.shared.technical;
    style: @fmt.shared.classic;
    layout: @fmt.shared.teaching;
    select: [@c.tables.orders, @d.model.support, @c.domains.customer_id, @d.model.binding];
    publication { width: 1730px; height: 700px; }
    legend { keys: { "model.r_order_domain": 1, "model.r_support_candidate": 2, "model.r_binding": 3 }; }

}

view diagram "09 / Namespace organization" {
    data: [@c.tables, @s.model, @n.model, @c.domains];
    format: @fmt.shared.technical;
    style: @fmt.shared.classic;
    layout: @fmt.shared.teaching;
    select: [@c.tables.orders, @s.model.routine, @n.model.schema];
    publication { width: 1370px; height: 640px; }
    legend { keys: { "model.r_orders_schema": 1, "model.r_routine_schema": 2 }; }

}

view diagram "10 / Shards, copies and placement" {
    data: [@c.tables, @d.model, @c.domains];
    format: @fmt.shared.technical;
    style: @fmt.shared.classic;
    layout: @fmt.shared.teaching;
    select: [@c.tables.orders, @d.model.shard, @d.model.primary, @d.model.follower, @d.model.local, @d.model.cloud];
    publication { width: 1600px; height: 1080px; }
    legend { keys: { "model.r_part": 1, "model.r_primary_fragment": 2, "model.r_follower_fragment": 3, "model.r_primary_host": 4, "model.r_follower_host": 5, "model.r_replication": 6 }; }
    display { fields: none; badges: none; }

    frame local "ON-PREMISES / placement view" { members: [@d.model.primary, @d.model.local]; }
    frame cloud "CLOUD / placement view" { members: [@d.model.follower, @d.model.cloud]; }
}

view diagram "11 / Data-flow diagram" {
    data: [@f.dfd];
    format: @fmt.shared.technical;
    style: @fmt.shared.classic;
    layout: @fmt.shared.row;
    select: [@f.dfd.incoming, @f.dfd.validate, @f.dfd.accepted];
    publication { width: 1580px; height: 440px; }
    legend { keys: { "dfd.r_input": 1, "dfd.r_output": 2 }; }
}

view diagram "12 / Event publication and consumers" {
    data: [@f.stream, @c.tables, @c.domains];
    format: @fmt.shared.technical;
    style: @fmt.shared.classic;
    layout: @fmt.shared.teaching;
    select: [@f.stream.source, @f.stream.capture, @f.stream.topic, @f.stream.hist_job, @f.stream.search_job, @f.stream.history, @f.stream.search];
    publication { width: 1640px; height: 1090px; }
    legend { keys: { "stream.r_capture": 1, "stream.r_publish": 2, "stream.r_history_delivery": 3, "stream.r_search_delivery": 4, "stream.r_history_write": 5, "stream.r_search_write": 6 }; }
    display { fields: none; badges: none; }

}

view diagram "13 / Dataset lineage" {
    data: [@c.tables, @l.model, @c.domains];
    format: @fmt.shared.technical;
    style: @fmt.shared.classic;
    layout: @fmt.shared.row;
    select: [@c.tables.orders, @l.model.daily, @l.model.report];
    publication { width: 1580px; height: 440px; }
    legend { keys: { "model.r_aggregate": 1, "model.r_report": 2 }; }
}

view diagram "14 / Valid time and recorded time" {
    data: [@t.model];
    format: @fmt.shared.technical;
    style: @fmt.shared.classic;
    layout: @fmt.shared.teaching;
    select: [@t.model.history, @t.model.example];
    publication { width: 1700px; height: 850px; }
    legend { keys: { "model.r_example": 1 }; }

}

view diagram "15 / Dimensional warehouse" {
    data: [@w.model];
    format: @fmt.shared.technical;
    style: @fmt.shared.classic;
    layout: @fmt.shared.teaching;
    select: [@w.model.fact, @w.model.customer, @w.model.product, @w.model.date, @w.model.grain];
    publication { width: 1680px; height: 1050px; }
    legend { keys: { "model.r_c": 1, "model.r_p": 2, "model.r_d": 3 }; }

}

view diagram "16 / Vector and embedding lineage" {
    data: [@v.model];
    format: @fmt.shared.technical;
    style: @fmt.shared.neo;
    layout: @fmt.shared.row;
    select: [@v.model.source, @v.model.embedding, @v.model.index];
    publication { width: 1580px; height: 440px; }
    legend { keys: { "model.r_input": 1, "model.r_output": 2 }; }
}

view diagram "17 / Data products and contracts" {
    data: [@g.model];
    format: @fmt.shared.technical;
    style: @fmt.shared.classic;
    layout: @fmt.shared.row;
    select: [@g.model.product, @g.model.contract, @g.model.team];
    publication { width: 1580px; height: 440px; }
    legend { keys: { "model.r_contract": 1, "model.r_owner": 2 }; }
}

view diagram "18 / Data handling boundaries" {
    data: [@s.model];
    format: @fmt.shared.technical;
    style: @fmt.shared.classic;
    layout: @fmt.shared.row;
    select: [@s.model.source, @s.model.mask, @s.model.export];
    publication { width: 1580px; height: 440px; }
    legend { keys: { "model.r_input": 1, "model.r_output": 2 }; }
    frame restricted "RESTRICTED / view scope" { scope: @s.model.restricted; members: [@s.model.source]; }
    frame review "REVIEW BEFORE RELEASE / view scope" { scope: @s.model.egress; members: [@s.model.export]; }
}

view diagram "19 / Backup and restore design" {
    data: [@r.model];
    format: @fmt.shared.technical;
    style: @fmt.shared.classic;
    layout: @fmt.shared.row;
    select: [@r.model.backup, @r.model.restore, @r.model.target];
    publication { width: 1580px; height: 440px; }
    legend { keys: { "model.r_restore": 1, "model.r_output": 2 }; }
}

view diagram "20 / Migration and target design" {
    data: [@m.model];
    format: @fmt.shared.technical;
    style: @fmt.shared.classic;
    layout: @fmt.shared.row;
    select: [@m.model.legacy, @m.model.convert, @m.model.target];
    publication { width: 1580px; height: 440px; }
    legend { keys: { "model.r_extract": 1, "model.r_load": 2 }; }
}

view diagram "21 / Example-driven data quality" {
    data: [@q.model];
    format: @fmt.shared.technical;
    style: @fmt.shared.classic;
    layout: @fmt.shared.row;
    select: [@q.model.input, @q.model.check, @q.model.expected];
    publication { width: 2130px; height: 440px; }
    legend { keys: { "model.r_input": 1, "model.r_result": 2 }; }
}

view diagram "22 / Navigable design documentation" {
    data: [@c.tables, @c.domains]; format: @fmt.shared.technical;
    display: @fmt.shared.compact;
    select: [@c.tables.orders, @c.tables.customer];
    publication { width: 1580px; height: 780px; }
    legend { keys: { "tables.r_order_customer": 1 }; }
    subdiagram logical { view: @logical_detail; mode: reference; label: "Logical detail"; }
    subdiagram business { view: @business_detail; mode: reference; label: "Business concepts"; }
}

view context "Synthetic shop / C4 context" {
    data: [@shop]; format: @shared.styles.technical;
    projection { kind: graph; profile: "c4.context@1"; }
    select: [@shop.customer, @shop.site, @shop.mailer];
    display { fields: none; }
    layout: @options.c4ctx;
    publication { size: content; fit: none; overflow: error; minimum_text: 8pt; }
}

view container "Synthetic shop / C4 container" {
    data: [@shop]; format: @shared.styles.technical;
    projection { kind: graph; profile: "c4.container@1"; }
    select: [@shop.customer, @shop.site, @shop.web, @shop.db, @shop.events];
    display { fields: none; }
    layout: @options.c4grid;
    frame system_boundary { scope: @shop.site; members: [@shop.web, @shop.db, @shop.events]; }
    publication { size: content; fit: none; overflow: error; minimum_text: 8pt; }
}

view component "Synthetic shop / C4 component" {
    data: [@shop]; format: @shared.styles.technical;
    projection { kind: graph; profile: "c4.component@1"; }
    select: [@shop.customer, @shop.web, @shop.checkout, @shop.cart, @shop.db];
    display { fields: none; }
    layout: @options.c4layered;
    frame container_boundary { scope: @shop.web; members: [@shop.checkout, @shop.cart]; }
    publication { size: content; fit: none; overflow: error; minimum_text: 8pt; }
}

view lan "Office LAN" {
    data: [@m]; format: @shared.styles.technical;
    select: [@m.office_bus, @m.core_switch, @m.file_server, @m.app_server, @m.uplink];
    projection { kind: graph; profile: "network.basic@1"; }
    layout { algorithm: layered; direction: down; }
    publication { size: content; fit: none; overflow: error; minimum_text: 8pt; }
    place @m.office_bus { size: [420px, 28px]; }
}

view net "Network symbol library" {
    data: [@m];
    projection { profile: "network.basic@1"; }
    publication { size: content; fit: none; }
}

view main "UML deployment / nodes and artifacts" {
    data: [@shop];
    projection { profile: "uml.deployment@1"; }
    publication { size: content; fit: none; }
}

view chart "ISO 5807 warehouse flow" {
    data: [@m];
    projection { kind: graph; profile: "flow.iso5807@1"; }
    layout { algorithm: layered; direction: down; }
    publication { size: content; fit: none; }
}

view deployment "Shop deployment" {
    data: [@dep];
    projection { profile: "c4.deployment@1"; }
    frame rack "Shop server" { scope: @dep.appbox; members: [@dep.war]; }
    publication { size: content; fit: none; }
}

view dynamic "Browse dynamic" {
    data: [@dyn];
    projection { profile: "c4.dynamic@1"; }
    publication { size: content; fit: none; }
}

view fragments "UML sequence / fragments and gates" {
    data: [@ordering];
    projection { kind: sequence; profile: "uml.sequence@2"; }
    publication { size: content; fit: none; }
}

view raci "03 / Model-derived RACI" {
    data: [@m.process, @m.roles, @m.responsibilities];
    format: @f.shared.common;
    projection { kind:matrix;profile:"matrix.raci@1";rows:[@m.process.order, @m.process.receive, @m.process.post];columns:[@m.roles.buyer, @m.roles.manager, @m.roles.warehouse, @m.roles.controller];relation:"analysis.assignment";value:"x_assignment.code"; }

}

view crud "04 / Model-derived CRUD" {
    data: [@m.process, @m.schema, @m.access];
    format: @f.shared.common;
    projection { kind:matrix;profile:"matrix.crud@1";rows:[@m.process.order, @m.process.receive, @m.process.post];columns:[@m.schema.supplier, @m.schema.po, @m.schema.receipt];relation:"analysis.access";value:"x_assignment.code"; }

}

view matrix_general "26 / General relationship matrix" {
    data: [@m.process, @m.roles, @m.responsibilities];
    format: @f.shared.common;
    projection { kind:matrix;profile:"matrix.relations@1";rows:[@m.process.order, @m.process.receive, @m.process.post];columns:[@m.roles.buyer, @m.roles.manager, @m.roles.warehouse, @m.roles.controller];relation:"analysis.assignment";value:"name"; }

}

view record_table "19 / Shared observation table" {
    data: [@m.facts];
    format: @f.shared.common;
    projection { kind:table;profile:"table.records@1";records:[@m.facts.m1, @m.facts.m2, @m.facts.m3, @m.facts.m4, @m.facts.m5, @m.facts.m6];columns:[{key:"x_record.month",label:"Month"},{key:"x_record.value",label:"Recorded value (CAD)"},{key:"x_record.cost",label:"Illustrative cost (CAD)"},{key:"x_record.count",label:"Count"}]; }

}

view decision_unique "14 / Disposition policy — unique" {
    data: [@m.rules];
    format: @f.shared.common;
    projection { kind: "decision"; profile: "decision.rules@1"; records: [@m.rules.high, @m.rules.low_pass, @m.rules.low_review]; inputs: [{ "key": "severity", "type": "enum", "values": ["low", "high"] }, { "key": "score", "type": "number", "min": 0, "max": 10 }]; outputs: ["route", "audit"]; hit_policy: "unique"; coverage: "complete"; analysis_budget: 4096; }
    select: [@m.rules.high, @m.rules.low_pass, @m.rules.low_review];

}

view decision_collect "14 / Disposition policy — collect" {
    data: [@m.rules];
    format: @f.shared.common;
    projection { kind: "decision"; profile: "decision.rules@1"; records: [@m.rules.high, @m.rules.check, @m.rules.audit]; inputs: [{ "key": "severity", "type": "enum", "values": ["low", "high"] }, { "key": "score", "type": "number", "min": 0, "max": 10 }]; outputs: ["route", "audit"]; hit_policy: "collect"; coverage: "complete"; analysis_budget: 4096; }
    select: [@m.rules.high, @m.rules.check, @m.rules.audit];

}

view heat_numeric "02 / Review score — numeric" {
    data: [@m.responsibilities];
    format: @f.shared.common;
    projection { kind: "matrix"; write_data: @m.responsibilities; profile: "matrix.heatmap@1"; rows: [@m.responsibilities.inspect, @m.responsibilities.contain, @m.responsibilities.correct]; columns: [@m.responsibilities.plant_a, @m.responsibilities.plant_b, @m.responsibilities.plant_c]; relation: "assoc"; value: "x_record.score"; encoding: { "mode": "numeric", "domain": [0, 10], "palette": "blue" }; }
    select: [@m.responsibilities.inspect, @m.responsibilities.contain, @m.responsibilities.correct, @m.responsibilities.plant_a, @m.responsibilities.plant_b, @m.responsibilities.plant_c];

}

view heat_bands "02 / Review score — bands" {
    data: [@m.responsibilities];
    format: @f.shared.common;
    projection { kind: "matrix"; write_data: @m.responsibilities; profile: "matrix.heatmap@1"; rows: [@m.responsibilities.inspect, @m.responsibilities.contain, @m.responsibilities.correct]; columns: [@m.responsibilities.plant_a, @m.responsibilities.plant_b, @m.responsibilities.plant_c]; relation: "assoc"; value: "x_record.score"; encoding: { "mode": "bands", "boundaries": [0, 3, 7, 11], "labels": ["Low", "Watch", "Action"], "palette": "blue" }; }
    select: [@m.responsibilities.inspect, @m.responsibilities.contain, @m.responsibilities.correct, @m.responsibilities.plant_a, @m.responsibilities.plant_b, @m.responsibilities.plant_c];

}

view heat_categories "02 / Review score — categories" {
    data: [@m.responsibilities];
    format: @f.shared.common;
    projection { kind: "matrix"; write_data: @m.responsibilities; profile: "matrix.heatmap@1"; rows: [@m.responsibilities.inspect, @m.responsibilities.contain, @m.responsibilities.correct]; columns: [@m.responsibilities.plant_a, @m.responsibilities.plant_b, @m.responsibilities.plant_c]; relation: "assoc"; value: "x_record.status"; encoding: { "mode": "category", "values": ["Good", "Monitor", "Action"], "labels": ["Good", "Monitor", "Action"], "palette": "blue" }; }
    select: [@m.responsibilities.inspect, @m.responsibilities.contain, @m.responsibilities.correct, @m.responsibilities.plant_a, @m.responsibilities.plant_b, @m.responsibilities.plant_c];

}

view swot "23 / Reusable SWOT panel template" {
    data: [@m.notes];
    format: @f.shared.common;
    projection { kind:panels;profile:"panels.basic@1";columns:2;panels:[{id:"s",title:"STRENGTHS",row:0,column:0,rowspan:1,colspan:1,items:[@m.notes.strength]}, {id:"w",title:"WEAKNESSES",row:0,column:1,rowspan:1,colspan:1,items:[@m.notes.weakness]}, {id:"o",title:"OPPORTUNITIES",row:1,column:0,rowspan:1,colspan:1,items:[@m.notes.opportunity]}, {id:"t",title:"THREATS",row:1,column:1,rowspan:1,colspan:1,items:[@m.notes.threat]}]; }

}

view sipoc "24 / SIPOC from shared notes" {
    data: [@m.notes];
    format: @f.shared.common;
    projection { kind:panels;profile:"panels.basic@1";columns:5;width:1650px;panels:[{id:"supplier",title:"SUPPLIER",row:0,column:0,rowspan:1,colspan:1,items:[@m.notes.supplier]}, {id:"inputs",title:"INPUTS",row:0,column:1,rowspan:1,colspan:1,items:[@m.notes.inputs]}, {id:"process",title:"PROCESS",row:0,column:2,rowspan:1,colspan:1,items:[@m.notes.process]}, {id:"outputs",title:"OUTPUTS",row:0,column:3,rowspan:1,colspan:1,items:[@m.notes.outputs]}, {id:"customers",title:"CUSTOMERS",row:0,column:4,rowspan:1,colspan:1,items:[@m.notes.customers]}]; }

}

view journey "25 / Service journey with spanning panels" {
    data: [@m.notes];
    format: @f.shared.common;
    projection { kind:panels;profile:"panels.basic@1";columns:3;panels:[{id:"input",title:"INPUT AND EXPECTATION",row:0,column:0,rowspan:1,colspan:1,items:[@m.notes.inputs]}, {id:"p",title:"PROCESS",row:0,column:1,rowspan:1,colspan:1,items:[@m.notes.process]}, {id:"out",title:"OUTPUT",row:0,column:2,rowspan:1,colspan:1,items:[@m.notes.outputs]}, {id:"actor",title:"ACTOR EXPERIENCE",row:1,column:0,rowspan:1,colspan:3,items:[@m.notes.journey]}, {id:"verify",title:"VERIFICATION AND REVIEW",row:2,column:0,rowspan:1,colspan:3,items:[@m.notes.verification, @m.notes.review]}]; }

}

view empathy "Support team / empathy map" {
    data: [@research];
    format: @shared.styles.technical;
    projection { kind:panels; profile:"canvas.empathy@1"; columns:2; panels:[
        {id:"says",title:"SAYS",row:0,column:0,rowspan:1,colspan:1,items:[@research.says_a, @research.says_b]},
        {id:"thinks",title:"THINKS",row:0,column:1,rowspan:1,colspan:1,items:[@research.thinks]},
        {id:"persona",title:"PERSONA",row:1,column:0,rowspan:1,colspan:2,items:[@research.persona]},
        {id:"does",title:"DOES",row:2,column:0,rowspan:1,colspan:1,items:[@research.does]},
        {id:"feels",title:"FEELS",row:2,column:1,rowspan:1,colspan:1,items:[@research.feels]}]; }
}

view storymap "Shop rebuild / story map" {
    data: [@shop];
    format: @shared.styles.technical;
    projection { kind:matrix; profile:"matrix.storymap@1"; rows:[@shop.r1, @shop.r2]; columns:[@shop.browse, @shop.configure, @shop.checkout, @shop.pay, @shop.fulfil]; relation:"assoc"; value:"x_story.task"; duplicates:join; }
}

view chart_line "13 / Synthetic monthly value \u2014 line" {
    data: [@m.facts];
    format: @f.shared.common;
    projection { kind:chart;profile:"chart.basic@1";records:[@m.facts.m1, @m.facts.m2, @m.facts.m3, @m.facts.m4, @m.facts.m5, @m.facts.m6];mark:line;x:"x_record.month";y:"x_record.value";unit:"CAD";width:1120px;height:620px; }

}

view chart_area "14 / Synthetic monthly value \u2014 area" {
    data: [@m.facts];
    format: @f.shared.common;
    projection { kind:chart;profile:"chart.basic@1";records:[@m.facts.m1, @m.facts.m2, @m.facts.m3, @m.facts.m4, @m.facts.m5, @m.facts.m6];mark:area;x:"x_record.month";y:"x_record.value";unit:"CAD";width:1120px;height:620px; }

}

view chart_pie "15 / Synthetic monthly value \u2014 pie" {
    data: [@m.facts];
    format: @f.shared.common;
    projection { kind:chart;profile:"chart.basic@1";records:[@m.facts.m1, @m.facts.m2, @m.facts.m3, @m.facts.m4, @m.facts.m5, @m.facts.m6];mark:pie;x:"x_record.month";y:"x_record.value";unit:"CAD";width:1120px;height:620px; }

}

view scatter "17 / Cost versus recorded value" {
    data: [@m.facts];
    format: @f.shared.common;
    projection { kind:chart;profile:"chart.basic@1";records:[@m.facts.m1, @m.facts.m2, @m.facts.m3, @m.facts.m4, @m.facts.m5, @m.facts.m6];mark:point;x:"x_record.cost";x_type:number;y:"x_record.value";size:"x_record.count";unit:"CAD"; }

}

view time_series "18 / UTC monthly observations" {
    data: [@m.facts];
    format: @f.shared.common;
    projection { kind:chart;profile:"chart.basic@1";records:[@m.facts.m1, @m.facts.m2, @m.facts.m3, @m.facts.m4, @m.facts.m5, @m.facts.m6];mark:line;x:"x_record.date";x_type:date;y:"x_record.value";unit:"CAD"; }

}

view grouped_bars "06 / Defects — grouped bars" {
    data: [@m.series];
    format: @f.shared.common;
    projection { kind: "chart"; profile: "chart.quality@1"; records: [@m.series.s0_0, @m.series.s0_1, @m.series.s0_2, @m.series.s1_0, @m.series.s1_1, @m.series.s1_2]; x: "x_record.stage"; y: "x_record.count"; series: "x_record.series"; unit: "defects"; mark: "bar"; arrangement: "group"; }

}

view stacked_bars "06 / Defects — stacked bars" {
